/**
 * about-assets.js — 「关于」页签的两张联系方式二维码（**内联 base64 数据 URI**）。
 *
 * 为什么内联而不是走宿主路由：这两张图是**随包发布的静态美术**（同吉祥物立绘，见
 * assets/mascot/README.md 的同一口径）—— 桌面壳的能力头栅栏（x-dsh-desktop-renderer）
 * 对"原图直出"的路由是一道额外的门，而内联进客户端 bundle 的 data URI 走的是渲染页
 * 自己的内存，任何宿主形态下都显示得出来，也不会在设置页打开时多发一次请求。
 * 源资产（未压缩的原始截图）归档在 `assets/about/`，**不进 npm 包**；本文件里的两份
 * 是缩到 520px 宽、128 色调色板的派生版本（再次生成的口径见 assets/about/README.md）。
 *
 * 契约（构建期由 scripts/build-client.mjs 内联进 bundle 的工厂作用域）：纯数据、零依赖，
 * 必须保持浏览器安全（无 import / require / Node API）。
 */

// 项目仓库（README / package.json 的同一条地址）：关于页的按钮与可复制文本都用它。
const ABOUT_REPO_URL = "https://github.com/elysia395/dsh-wallpaper-engine";

